interface ShadowLogoProps {
  className?: string;
  variant?: "wordmark" | "emblem" | "stacked" | "inline";
}

export default function ShadowLogo({
  className = "h-6 w-auto",
  variant = "wordmark",
}: ShadowLogoProps) {
  if (variant === "emblem") {
    return <ShadowEmblem className={className} />;
  }

  if (variant === "inline") {
    return (
      <div className={`inline-flex items-center gap-3 ${className}`}>
        <ShadowEmblem className="h-full w-auto aspect-square flex-shrink-0" />
        <svg
          viewBox="0 0 534 61"
          fill="currentColor"
          xmlns="http://www.w3.org/2000/svg"
          className="h-[75%] w-auto"
          aria-label="SHADOW"
          role="img"
        >
          <path fillRule="evenodd" d={SHADOW_WORDMARK_PATH} />
        </svg>
      </div>
    );
  }

  if (variant === "stacked") {
    return (
      <svg
        viewBox="0 0 600 420"
        fill="currentColor"
        xmlns="http://www.w3.org/2000/svg"
        className={className}
        aria-label="SHADOW"
        role="img"
      >
        {/* Emblem centered at top */}
        <g transform="translate(185.00, 40.00) scale(0.9055)">
          <path fillRule="evenodd" d={SHADOW_EMBLEM_PATH} />
        </g>
        {/* Wordmark centered below */}
        <g transform="translate(75.00, 320.00) scale(0.8427)">
          <path fillRule="evenodd" d={SHADOW_WORDMARK_PATH} />
        </g>
      </svg>
    );
  }

  // Default: wordmark
  return (
    <svg
      viewBox="0 0 534 61"
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="SHADOW"
      role="img"
    >
      <path fillRule="evenodd" d={SHADOW_WORDMARK_PATH} />
    </svg>
  );
}
